}
function title(slide, text, sub) {
  slide.addText(text, { x: 0.48, y: 0.28, w: 8.7, h: 0.42, fontFace: 'Aptos Display', fontSize: 21, bold: true, color: C.navy, margin: 0, breakLine: false, fit: 'shrink' });
  if (sub) slide.addText(sub, { x: 0.5, y: 0.74, w: 8.4, h: 0.26, fontSize: 8.5, color: C.muted, margin: 0, breakLine: false, fit: 'shrink' });
}
function metric(slide, x, y, w, value, label, color = C.blue) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.8, rectRadius: 0.06, fill: { color: C.card }, line: { color: 'E2E8F0', width: 0.7 }, shadow: { type: 'outer', color: '000000', opacity: 0.08, blur: 1, angle: 45, distance: 1 } });
  slide.addText(value, { x: x + 0.12, y: y + 0.11, w: w - 0.24, h: 0.28, fontSize: 19, bold: true, color, margin: 0, breakLine: false, fit: 'shrink' });
  slide.addText(label, { x: x + 0.13, y: y + 0.47, w: w - 0.26, h: 0.2, fontSize: 7.5, color: C.slate, margin: 0, fit: 'shrink' });
}
function note(slide, x, y, w, h, text, color = C.teal) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.05, fill: { color }, line: { color, transparency: 100 } });
  slide.addText(text, { x: x + 0.15, y: y + 0.12, w: w - 0.3, h: h - 0.22, fontSize: 10, bold: true, color: 'FFFFFF', margin: 0.01, fit: 'shrink', valign: 'mid' });
}
function bullet(slide, lines, x, y, w, h, color = C.navy) {
  slide.addText(lines.map(t => ({ text: t, options: { bullet: { type: 'ul' }, breakLine: true } })), { x, y, w, h, fontSize: 10.5, color, breakLine: false, margin: 0.02, fit: 'shrink', paraSpaceAfterPt: 6, valign: 'top' });
}
function label(slide, text, x, y, w, h, opts = {}) {
