}
function drawMiniBars(slide, x, y, w, h, data, max, palette) {
  const gap = 0.06;
  const bw = (w - gap * (data.length - 1)) / data.length;
  data.forEach((d, i) => {
    const bh = (d.v / max) * h;
    const bx = x + i * (bw + gap);
    slide.addShape(pptx.ShapeType.rect, { x: bx, y: y + h - bh, w: bw, h: bh, fill: { color: palette[i % palette.length] }, line: { color: palette[i % palette.length], transparency: 100 } });
    label(slide, d.l, bx - 0.01, y + h + 0.07, bw + 0.02, 0.15, { size: 6.2, align: 'center' });
    label(slide, d.t, bx - 0.02, y + h - bh - 0.18, bw + 0.04, 0.13, { size: 6.5, align: 'center', bold: true, color: C.navy });
  });
}
function drawHBar(slide, x, y, w, h, data, max, highlightNames = []) {
  const row = h / data.length;
  data.forEach((d, i) => {
    const yy = y + i * row + 0.035;
    const barW = (d.salary / max) * w;
    const col = highlightNames.includes(d.name) ? C.blue : (i < 3 ? C.teal : C.cyan);
    label(slide, d.name, x - 1.62, yy + 0.015, 1.48, 0.16, { size: 7.3, color: C.navy, bold: i < 3 });
    slide.addShape(pptx.ShapeType.rect, { x, y: yy, w, h: 0.15, fill: { color: 'E2E8F0' }, line: { color: 'E2E8F0', transparency: 100 } });
    slide.addShape(pptx.ShapeType.rect, { x, y: yy, w: barW, h: 0.15, fill: { color: col }, line: { color: col, transparency: 100 } });
    label(slide, `$${Math.round(d.salary/1000)}K`, x + barW + 0.08, yy - 0.005, 0.55, 0.16, { size: 7.2, bold: true, color: C.navy });
  });
}
function drawScatter(slide, x, y, w, h, data, opt = {}) {
  const xMin = opt.xMin ?? 0, xMax = opt.xMax;
  const yMin = opt.yMin ?? 0, yMax = opt.yMax;
  const tickColor = 'E2E8F0';
  slide.addShape(pptx.ShapeType.line, { x, y: y + h, w, h: 0, line: { color: C.slate, width: 1 } });
  slide.addShape(pptx.ShapeType.line, { x, y, w: 0, h, line: { color: C.slate, width: 1 } });
  for (let i = 1; i <= 4; i++) {
    const gx = x + (w * i / 4);
    const gy = y + (h * i / 4);
    slide.addShape(pptx.ShapeType.line, { x: gx, y, w: 0, h, line: { color: tickColor, width: 0.5, transparency: 15 } });
    slide.addShape(pptx.ShapeType.line, { x, y: gy, w, h: 0, line: { color: tickColor, width: 0.5, transparency: 15 } });
  }
  label(slide, opt.xLabel || 'Avg. years experience', x + w/2 - 0.7, y + h + 0.28, 1.4, 0.15, { size: 7, align: 'center' });
  label(slide, opt.yLabel || 'Median salary (USD)', x - 0.52, y + h/2 + 0.4, 1.2, 0.15, { size: 7, align: 'center', rotate: 270 });
  const yTicks = opt.yTicks || [];
  yTicks.forEach(t => {
    const py = y + h - ((t - yMin) / (yMax - yMin)) * h;
    label(slide, `$${Math.round(t/1000)}K`, x - 0.48, py - 0.07, 0.35, 0.12, { size: 6.2, align: 'right' });
  });
  const xTicks = opt.xTicks || [];
  xTicks.forEach(t => {
    const px = x + ((t - xMin) / (xMax - xMin)) * w;
    label(slide, String(t), px - 0.12, y + h + 0.08, 0.24, 0.12, { size: 6.2, align: 'center' });
  });
  data.forEach(d => {
    const px = x + ((d.exp - xMin) / (xMax - xMin)) * w;
    const py = y + h - ((d.salary - yMin) / (yMax - yMin)) * h;
    const col = d.color || opt.color || C.blue;
    slide.addShape(pptx.ShapeType.ellipse, { x: px - 0.055, y: py - 0.055, w: 0.11, h: 0.11, fill: { color: col, transparency: d.muted ? 35 : 0 }, line: { color: 'FFFFFF', width: 0.5 } });
